// ─────────────────────────────────────────────────────────────────────────────
// PRIVATE: getCandidateScoreCard
// Source: InterviewProcessService.getCandidateScoreCard
// List:   HRMSCandidateScoreCard
// ─────────────────────────────────────────────────────────────────────────────
async function _getCandidateScoreCard(candidateID: number): Promise<any[]> {
  try {
    const items: any[] = await SPServices.SPReadItems({
      Listname: ListNames.HRMSCandidateScoreCard,
      Select:
        "InterviewPanelID/ID,RelevantQualification,ReleventExperience,Knowledge,EnergyLevel,MeetJobRequirement,ContributeTowardsCultureRequried,Experience,OtherCriteriaScore,ConsiderForEmployment,Feedback,RecruitmentID/ID,Role/RoleTitle,InterviewPersonName/Title,OverAllEvaluationFeedback,Created,QuestionJson,Author/Title,Author/EMail",
      Expand:
        "InterviewPanelID,RecruitmentID,Role,InterviewPersonName,Author",
      Orderby: "ID",
      Orderbydecorasc: false,
      Filter: [
        {
          FilterKey: "InterviewPanelID/CandidateID/ID",
          Operator: "eq",
          FilterValue: candidateID,
        },
      ],
    });

    return items.map((score: any) => ({
      InterviewPanelID: score.InterviewPanelID?.ID || 0,
      RelevantQualification: score.RelevantQualification || "",
      ReleventExperience: score.ReleventExperience || "",
      Knowledge: score.Knowledge || "",
      EnergyLevel: score.EnergyLevel || "",
      MeetJobRequirement: score.MeetJobRequirement || "",
      ContributeTowardsCultureRequried:
        score.ContributeTowardsCultureRequried || "",
      Experience: score.Experience || "",
      OtherCriteriaScore: score.OtherCriteriaScore || "",
      ConsiderForEmployment: score.ConsiderForEmployment || "",
      Feedback: score.Feedback || "",
      RecruitmentID: score.RecruitmentID?.ID || 0,
      Role: score.Role?.RoleTitle || "",
      InterviewPersonName: score.InterviewPersonName?.Title || "",
      OverAllEvaluationFeedback: score.OverAllEvaluationFeedback || "",
      CreatedDate: score.Created
        ? new Date(score.Created).toLocaleString()
        : "",
      QuestionJson: score.QuestionJson ? JSON.parse(score.QuestionJson) : [],
      Author: {
        EMail: score.Author?.EMail || "",
        Title: score.Author?.Title || "",
      },
    }));
  } catch (err) {
    console.error("_getCandidateScoreCard error:", err);
    return [];
  }
}
// ─── NEW: fetchReviewScorecardJobs ─────────────────────────────
export async function fetchReviewScorecardJobs(currentUserEmail?: string): Promise<any[]> {
  try {
    const filterArray: any[] = [];
    if (currentUserEmail) {
      filterArray.push({
        FilterKey: "HOD",
        Operator: "eq",
        FilterValue: currentUserEmail,
      });
    }

    // Add any shared filter if needed, e.g. ItemCreated=No
    filterArray.push({
      FilterKey: "ItemCreated",
      Operator: "eq",
      FilterValue: "No",
    });
    filterArray.push({
      FilterKey: "StatusId",
      Operator: "eq",
      FilterValue: StatusId.RecruitmentInProgress,
    });
    const items: any[] = await SPServices.SPReadItems({
      Listname: ListNames.HRMSRecruitmentDptDetails,
      Select:
        "*,JobCode/JobCode,JobCode/ID,Status/StatusDescription,BusinessUnitCode/BusineesUnitCode",
      Expand: "JobCode,Status,BusinessUnitCode",
      Topcount: 5000,
      Orderby: "Created",
      Orderbydecorasc: false,
      FilterCondition: filterArray.length > 0 ? "and" : undefined,
      Filter: filterArray,
    });

    return items.map((item: any) => ({
      id: String(item.ID),
      recruitmentID: item.ID,
      jobCode: item?.JobCode?.JobCode || "",
      title: item?.JobTitle || "",
      buCode: item?.BusinessUnitCode?.BusineesUnitCode || "",
      posRequest: item?.NoOfPosition || "",
      nationality: item?.Nationality || "",
      status: item?.Status?.StatusDescription || "",
    }));
  } catch (err) {
    console.error("fetchReviewScorecardJobs error:", err);
    return [];
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. getInterviewPanelDetailsForScorecard
//    Source: InterviewProcessService.getInterviewPanelDetails
//    Lists:  HRMSInterviewPanelDetails + HRMSCandidateScoreCard
// ─────────────────────────────────────────────────────────────────────────────
export async function getInterviewPanelDetailsForScorecard(
  candidateID: number,
  employeeList: any[],
): Promise<any[]> {
  try {
    const interviewPanelItems: any[] = await SPServices.SPReadItems({
      Listname: ListNames.HRMSInterviewPanelDetails,
      Select:
        "*,ID,RecruitmentID/ID,InterviewLevel,InterviewPanel/Title,InterviewPanel/ID,CandidateID/ID,InterviewPanel/EMail",
      Expand: "RecruitmentID,InterviewPanel,CandidateID",
      Orderby: "ID",
      Orderbydecorasc: false,
      Filter: [
        {
          FilterKey: "CandidateID/Id",
          Operator: "eq",
          FilterValue: candidateID,
        },
      ],
    });

    const rawScores = await _getCandidateScoreCard(candidateID);
    const scoreCardMap = new Map<number, any>();
    rawScores.forEach((score) => scoreCardMap.set(score.InterviewPanelID, score));

    let sumOverallScores = 0;
    let sumQuestionScores = 0;
    let maxQuestionScore = 0;

    return interviewPanelItems.map((interview: any) => {
      const scoreCard = scoreCardMap.get(interview.ID) || null;

      const totalScore =
        (Number(scoreCard?.RelevantQualification) || 0) +
        (Number(scoreCard?.ReleventExperience) || 0) +
        (Number(scoreCard?.Knowledge) || 0) +
        (Number(scoreCard?.EnergyLevel) || 0) +
        (Number(scoreCard?.MeetJobRequirement) || 0) +
        (Number(scoreCard?.ContributeTowardsCultureRequried) || 0) +
        (Number(scoreCard?.Experience) || 0) +
        (Number(scoreCard?.OtherCriteriaScore) || 0);

      const questionData: any[] = scoreCard?.QuestionJson || [];
      const questionScore = questionData.reduce((sum: number, q: any) => {
        return sum + (Number(Object.values(q)[0]) || 0);
      }, 0);
      const maxQuestionScoreForPanel = questionData.length * 3;

      const level1Count = interviewPanelItems.filter(
        (p) =>
          p.InterviewLevel === "Level 1" && p.CandidateID?.ID === candidateID,
      ).length;
      const maxOverallScore = level1Count * 40;

      sumOverallScores += totalScore;
      sumQuestionScores += questionScore;
      maxQuestionScore += maxQuestionScoreForPanel;

      const maxPossibleScore = maxQuestionScore + maxOverallScore;
      const combinedScore = sumOverallScores + sumQuestionScores;
      const rawGpa =
        maxPossibleScore > 0 ? (combinedScore / maxPossibleScore) * 5 : 0;
      const gpa = Math.floor(rawGpa * 100) / 100;

      const email = scoreCard?.Author?.EMail?.toLowerCase() || "";
      const employee = employeeList.find(
        (emp) => emp.Email?.toLowerCase() === email,
      );
      const fullName = employee
        ? `${employee.FirstName ?? ""} ${employee.MiddleName ?? ""} ${employee.LastName ?? ""}`.trim()
        : scoreCard?.Author?.Title || "";

      return {
        ID: interview.ID,
        RecruitmentID: interview?.RecruitmentID?.ID || 0,
        InterviewLevel: interview.InterviewLevel || "",
        InterviewPanelTitle: [interview.InterviewPanel?.Title || ""],
        CandidateID: interview.CandidateID?.ID || 0,
        ScoreCard: scoreCard,
        GPA: gpa,
        TotalScore: totalScore,
        QuestionScore: questionScore,
        MaxOverallScore: maxOverallScore,
        MaxQuestionScore: maxQuestionScoreForPanel,
        SumOverallScores: totalScore,
        SumQuestionScores: questionScore,
        RelevantQualification: scoreCard?.RelevantQualification || "",
        ReleventExperience: scoreCard?.ReleventExperience || "",
        Knowledge: scoreCard?.Knowledge || "",
        EnergyLevel: scoreCard?.EnergyLevel || "",
        MeetJobRequirement: scoreCard?.MeetJobRequirement || "",
        ContributeTowardsCultureRequried:
          scoreCard?.ContributeTowardsCultureRequried || "",
        Experience: scoreCard?.Experience || "",
        OtherCriteriaScore: scoreCard?.OtherCriteriaScore || "",
        Id: interview.ID,
        comments: scoreCard?.Feedback || "",
        OverAllEvaluationFeedback: scoreCard?.OverAllEvaluationFeedback || "",
        Date: scoreCard?.CreatedDate ? new Date(scoreCard.CreatedDate) : null,
        Name: fullName,
        JobTitleInEnglish: employee?.JobTitle || "",
        JobTitleInFrench: employee?.JobTitleInFrench || "",
        Department: employee?.Department || "",
        RoleName: scoreCard?.Role || "",
        JobTitle: employee?.JobTitle || scoreCard?.Role || "",
        IsScoreSheetUploaded: interview.IsScoreSheetUploaded || "",
        InterviewPanel: interview.InterviewPanel?.Id || 0,
      };
    });
  } catch (err) {
    console.error("getInterviewPanelDetailsForScorecard error:", err);
    return [];
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. getPanelLevelTitles
//    Source: InterviewProcessService.GetPanelLeveldata
//    List:   HRMSInterviewPanelDetails
// ─────────────────────────────────────────────────────────────────────────────
export async function getPanelLevelTitles(
  candidateID: number,
  employeeList: any[],
): Promise<{ level1: string[]; level2: string[] }> {
  try {
    const listItems: any[] = await SPServices.SPReadItems({
      Listname: ListNames.HRMSInterviewPanelDetails,
      Select:
        "ID, CandidateID/ID, RecruitmentID/ID, InterviewLevel, InterviewPanel/Id, InterviewPanel/Title, InterviewPanel/EMail, IsScoreSheetUploaded",
      Expand: "InterviewPanel,RecruitmentID,CandidateID",
      Filter: [
        {
          FilterKey: "CandidateID/Id",
          Operator: "eq",
          FilterValue: candidateID,
        },
      ],
    });

    const groupedByLevel: Record<string, Set<string>> = {};

    listItems.forEach((item) => {
      const level = item.InterviewLevel || "Unknown";
      const email = item.InterviewPanel?.EMail?.toLowerCase() || "";
      const matched = employeeList.find(
        (emp: any) => emp.Email?.toLowerCase() === email,
      );
      const fullName = matched
        ? `${matched.FirstName ?? ""} ${matched.MiddleName ?? ""} ${matched.LastName ?? ""}`.trim()
        : item.InterviewPanel?.Title || "Unknown";

      if (!groupedByLevel[level]) groupedByLevel[level] = new Set();
      groupedByLevel[level].add(fullName);
    });

    return {
      level1: Array.from(groupedByLevel["Level 1"] ?? []),
      level2: Array.from(groupedByLevel["Level 2"] ?? []),
    };
  } catch (err) {
    console.error("getPanelLevelTitles error:", err);
    return { level1: [], level2: [] };
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. getCombinedCandidatePositionDetails
//    Source: InterviewProcessService.GetCombinedCandidatePositionDetails
//    Lists:  HRMSRecruitmentCandidatePersonalDetails + CV doc lib
// ─────────────────────────────────────────────────────────────────────────────
export async function getCombinedCandidatePositionDetails(
  filterParam: any[],
  filterConditions: any,
  employeeList: any[],
): Promise<any[]> {
  try {
    const candidateItems: any[] = await SPServices.SPReadItems({
      Listname: ListNames.HRMSRecruitmentCandidatePersonalDetails,
      Select:
        "*,JobCode/JobCode,AssignByInterviewPanel/EMail,RecruitmentID/ID,Status/ID,Status/StatusDescription,ID",
      Expand: "JobCode,AssignByInterviewPanel,RecruitmentID,Status",
      Filter: filterParam,
      FilterCondition: filterConditions,
      Topcount: TOP,
    });

    const formattedItems = await Promise.all(
      candidateItems.map(async (item, index) => {
        // ── CV doc ──────────────────────────────────────────────────────────
        let candidateCV: IDocFiles[] = [];
        const resumeLink = item?.CandidateResumeLink || "";
        if (resumeLink) {
          try {
            const extractedPath =
              resumeLink.split("/root:/")[1]?.split(":/content")[0] || "";
            if (extractedPath) {
              const folderPath = extractedPath.substring(
                0,
                extractedPath.lastIndexOf("/"),
              );
              const fileName = extractedPath.split("/").pop();
              if (folderPath && fileName) {
                const files = (await SPServices.getDocLibFiles({
                  FilePath: `${DocumentLibraray.HRMSCareerPortalCandidateCV}/${folderPath}`,
                })) as IDocFiles[];
                candidateCV = files.filter((f) => f.name === fileName);
              }
            }
          } catch (e) {
            console.error("CV extract error:", e);
          }
        }

        // ── Panel + Score ────────────────────────────────────────────────────
        const panelResult = await getInterviewPanelDetailsForScorecard(
          item.ID,
          employeeList,
        );
        const lastGPA = panelResult.length
          ? panelResult[panelResult.length - 1].GPA
          : null;

        const fullName =
          `${item?.FristName ?? ""} ${item?.MiddleName ?? ""} ${item?.LastName ?? ""}`.trim();

        return {
          SNO: index + 1,
          ID: item.ID,
          RecruitmentID: item?.RecruitmentID?.ID,
          JobCode: item?.JobCode?.JobCode,
          JobCodeId: item?.JobCodeId,
          PassportID: item?.PassportID,
          FristName: item?.FristName,
          MiddleName: item?.MiddleName,
          LastName: item?.LastName,
          FullName: fullName,
          ResidentialAddress: item?.ResidentialAddress,
          DOB: item?.DOB,
          ContactNumber: item?.ContactNumber,
          Email: item?.Email,
          Nationality: item?.Nationality,
          Gender: item?.Gender,
          TotalYearOfExperiance: item?.TotalYearOfExperiance,
          Skills: item?.Skills,
          LanguageKnown: item?.LanguageKnown,
          ReleventExperience: item?.ReleventExperience,
          Qualification: item?.Qualification,
          CandidateCVDoc: candidateCV,
          Status: item?.Status?.StatusDescription || "",
          StatusId: item?.StatusId,
          PositionTitle: item.PositionTitle,
          JobGrade: item.JobGrade,
          ExternalAgentDetails: { AgentName: item?.ExternalAgentDetails },
          HRMSCandidateScoreCard: panelResult,
          GPA: lastGPA,
          JobRequestID: item?.JobRequestID,
          InterviewDate: item?.InterviewDate,
          ConflictsOfInterest: item?.ConflictsOfInterest,
          disability: item?.Disability,
          disabilityReason: item?.DisabilityDetails,
          NationalityCode: item?.NationalityCode,
        };
      }),
    );

    return formattedItems;
  } catch (err) {
    console.error("getCombinedCandidatePositionDetails error:", err);
    return [];
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. fetchCandidateList  (used by ReviewScorecardCandidateList)
//    Source: CandidateList.fetchAllData
//    Lists:  HRMSRecruitmentDptDetails, HRMSGradeMaster,
//            HRMSRecruitmentCandidatePersonalDetails
// ─────────────────────────────────────────────────────────────────────────────
export async function fetchCandidateList(
  recruitmentID: number,
  jobCodeID: number,
  employeeList: any[],
): Promise<CandidateListRow[]> {
  // Grade from recruitment record
  const recruitRes: any[] = await SPServices.SPReadItems({
    Listname: ListNames.HRMSRecruitmentDptDetails,
    Select:
      "*,Department/DepartmentName,SubDepartment/SubDepTitle,Section/SectionName,DepartmentCode/DptCode,Status/StatusDescription,Action/Action,JobCode/JobCode,JobCode/ID,BusinessUnitCode/BusineesUnitCode,AssignedHR/Title",
    Filter: [{ FilterKey: "ID", Operator: "eq", FilterValue: recruitmentID }],
    Expand:
      "Department,SubDepartment,Section,DepartmentCode,Status,Action,JobCode,BusinessUnitCode",
    Topcount: TOP,
  });
  const grade: string = recruitRes[0]?.PatersonGrade ?? "";

  // Grade level
  const gradeLevelItems: any[] = await SPServices.SPReadItems({
    Listname: ListNames.HRMSGradeMaster,
    Select: "*",
    Filter: [
      { FilterKey: "PatersonGrade", Operator: "eq", FilterValue: grade },
    ],
  });
  const rawLevel: string = gradeLevelItems[0]?.Levels ?? "";
  const level = rawLevel === "2" ? "Level 1 & 2" : rawLevel;

  // Candidate list
  const candidateFilter = [
    {
      FilterKey: "RecruitmentIDId",
      Operator: "eq",
      FilterValue: recruitmentID,
    },
    { FilterKey: "JobCodeId", Operator: "eq", FilterValue: jobCodeID },
    {
      FilterKey: "StatusId",
      Operator: "in",
      FilterValue: [
        StatusId.PendingwithHODtoselectthecandidate,
        StatusId.Selected,
        StatusId.OnHoldbyHOD,
        StatusId.RejectedbyHOD,
        StatusId.PendingwithHODtoAssignPositionID,
        StatusId.PendingwithHODtoselectthecandidateLevel2,
        StatusId.CandidateOnHoldbyHODLevel1,
        StatusId.CandidateOnHoldbyHODLevel2,
        StatusId.CandidateRejectedbyHODLevel1,
        StatusId.CandidateRejectedbyHODLevel2,
      ],
    },
    { FilterKey: "ItemCreated", Operator: "eq", FilterValue: "No" },
  ];

  const rows = await getCombinedCandidatePositionDetails(
    candidateFilter,
    "and",
    employeeList,
  );

  return rows.map((item) => ({
    ...item,
    Grade: grade,
    InterviewLevel: level,
  }));
}

// ─────────────────────────────────────────────────────────────────────────────
// 5. fetchCandidateDetail  (single candidate – for HOD detail view)
// ─────────────────────────────────────────────────────────────────────────────
export async function fetchCandidateDetail(
  candidateID: number,
  employeeList: any[],
) {
  const rows = await getCombinedCandidatePositionDetails(
    [{ FilterKey: "ID", Operator: "eq", FilterValue: candidateID }],
    "",
    employeeList,
  );
  if (!rows.length) return {};
  const op = rows[0];
  const interviewLevels: string[] = Array.from(
    new Set(
      (op?.HRMSCandidateScoreCard as any[])?.map((i: any) => i.InterviewLevel) ??
        [],
    ),
  );
  return { ...op, InterviewLevels: interviewLevels };
}

// ─────────────────────────────────────────────────────────────────────────────
// 6. fetchGradeLevel
//    Source: RecruitmentProcessService.GetRecruitmentDetails + CommonService.GetGradeLevel
//    Lists:  HRMSRecruitmentDptDetails, HRMSGradeMaster
// ─────────────────────────────────────────────────────────────────────────────
export async function fetchGradeLevel(
  recruitmentID: number,
): Promise<InterviewedLevelValue> {
  const res: any[] = await SPServices.SPReadItems({
    Listname: ListNames.HRMSRecruitmentDptDetails,
    Select:
      "*,Department/DepartmentName,SubDepartment/SubDepTitle,Section/SectionName,DepartmentCode/DptCode,Status/StatusDescription,Action/Action,JobCode/JobCode,JobCode/ID,BusinessUnitCode/BusineesUnitCode,AssignedHR/Title",
    Filter: [{ FilterKey: "ID", Operator: "eq", FilterValue: recruitmentID }],
    Expand:
      "Department,SubDepartment,Section,DepartmentCode,Status,Action,JobCode,BusinessUnitCode",
    Topcount: TOP,
  });
  const grade: string = res[0]?.PatersonGrade ?? "";

  const gradeLevelItems: any[] = await SPServices.SPReadItems({
    Listname: ListNames.HRMSGradeMaster,
    Select: "*",
    Filter: [
      { FilterKey: "PatersonGrade", Operator: "eq", FilterValue: grade },
    ],
  });

  return {
    Grade: grade,
    Levels: gradeLevelItems[0]?.Levels ?? "",
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// 7. fetchScoreData  — raw scores → DataTable 1 (question rows) + DataTable 2
// ─────────────────────────────────────────────────────────────────────────────
export async function fetchScoreData(
  candidateID: number,
  employeeList: any[],
): Promise<{ rawScores: any[]; questionRows: QuestionScoreRow[] }> {
  const panelItems = await getInterviewPanelDetailsForScorecard(
    candidateID,
    employeeList,
  );
  const candidatePanels = panelItems.filter(
    (p) => p.CandidateID === candidateID,
  );
  const rawScores: any[] = candidatePanels.flatMap((c) => {
    const score = c.ScoreCard;
    return score && c.ID === score.InterviewPanelID ? [score] : [];
  });

  // Question rows (DataTable 1)
  const questionMap: Record<string, any> = {};
  rawScores.forEach((score, idx) => {
    if (score.QuestionJson) {
      score.QuestionJson.forEach((q: any) => {
        const key = Object.keys(q)[0];
        if (!questionMap[key]) questionMap[key] = { criteria: key };
        questionMap[key][`interviewer_${idx + 1}`] = q[key];
      });
    }
  });

  return { rawScores, questionRows: Object.values(questionMap) };
}

// ─────────────────────────────────────────────────────────────────────────────
// 8. buildOverallScoreRows  — pure transform (no SP call)
//    Mirrors: HodViewScorecard.transformScoreData
// ─────────────────────────────────────────────────────────────────────────────
export function buildOverallScoreRows(rawScores: any[]): OverallScoreRow[] {
  const criteria = [
    { field: "RelevantQualification",            label: "Qualification (Relevant)" },
    { field: "ReleventExperience",               label: "Experience (Relevant)" },
    { field: "Knowledge",                        label: "Knowledge" },
    { field: "EnergyLevel",                      label: "Energy Level" },
    { field: "MeetJobRequirement",               label: "Meets All Job Requirements" },
    {
      field: "ContributeTowardsCultureRequried",
      label: "Will Contribute to the Culture Required",
    },
    { field: "Experience",                       label: "Experience" },
    { field: "OtherCriteriaScore",              label: "Other Criteria Recognized by Panel" },
    { field: "ConsiderForEmployment",            label: "To Consider for Employment (Yes/No)" },
  ];

  const rows: OverallScoreRow[] = criteria.map((c) => {
    const row: OverallScoreRow = { criteria: c.label, total: 0 };
    rawScores.forEach((score, idx) => {
      if (c.field === "ConsiderForEmployment") {
        row[`interviewer_${idx + 1}`] = score.ConsiderForEmployment ?? "";
      } else {
        const val = Number(score[c.field]) || 0;
        row.total += val;
        row[`interviewer_${idx + 1}`] = val;
      }
    });
    return row;
  });

  const totalRow: OverallScoreRow = { criteria: "Total", total: 0 };
  rawScores.forEach((_, idx) => {
    const sum = rows.reduce((acc, r) => {
      const v = r[`interviewer_${idx + 1}`];
      return typeof v === "number" ? acc + v : acc;
    }, 0);
    totalRow[`interviewer_${idx + 1}`] = `${sum} / 40`;
    totalRow.total += sum;
  });
  rows.push(totalRow);
  return rows;
}

// ─────────────────────────────────────────────────────────────────────────────
// 9. fetchComments
//    Source: InterviewProcessService.getInterviewPanelDetails (level1)
//            InterviewProcessService.getCandidateLevel2ScoreCardData (level2)
//    Lists:  HRMSInterviewPanelDetails, HRMSCandidateLevel2ScoreCard
// ─────────────────────────────────────────────────────────────────────────────
export async function fetchComments(
  candidateID: number,
  employeeList: any[],
): Promise<{ level1: CommentsData[]; level2: CommentsData[] }> {
  const [l1Raw, l2Raw] = await Promise.all([
    getInterviewPanelDetailsForScorecard(candidateID, employeeList),
    (async () => {
      const items: any[] = await SPServices.SPReadItems({
        Listname: ListNames.HRMSCandidateLevel2ScoreCard,
        Select:
          "*,ID,CandidateID/ID,CandidateID/Title,Comments,Role/ID,Role/RoleTitle,Level,Author/EMail,Author/Title",
        Expand: "CandidateID,Role,Author",
        Filter: [
          {
            FilterKey: "CandidateID/Id",
            Operator: "eq",
            FilterValue: candidateID,
          },
        ],
      });
      return items.map((objresult: any) => {
        const email = objresult.Author?.EMail?.toLowerCase() ?? "";
        const employee = employeeList.find(
          (emp: any) => emp.Email?.toLowerCase() === email,
        );
        return {
          Id: objresult.ID ?? 0,
          CandidateID: objresult.CandidateID?.ID ?? 0,
          RoleId: objresult.Role?.ID ?? 0,
          RoleTitle: objresult.Role?.RoleTitle ?? "",
          comments: objresult.Comments ?? "",
          Level: objresult.Level ?? "",
          JobTitleInEnglish: employee?.JobTitle ?? "",
          JobTitleInFrench: employee?.JobTitleInFrench ?? "",
          Department: "",
          Date: objresult.Created ? new Date(objresult.Created) : null,
          JobTitle: "",
          RoleName: objresult.Role?.RoleTitle ?? "",
          Name: employee
            ? `${employee.FirstName ?? ""} ${employee.MiddleName ?? ""} ${employee.LastName ?? ""}`.trim()
            : objresult.Author?.Title || "",
        };
      });
    })(),
  ]);

  return {
    level1: (l1Raw as any[]).filter((i) => i.CandidateID === candidateID),
    level2: (l2Raw as CommentsData[]).filter(
      (i: any) => i.CandidateID === candidateID,
    ),
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// 10. fetchQuestionnaire
//     Source: GetPortalJobs.getQuestionnaire
//     Step A: GetJobUniqueDataValue – LIST: RecruitAppCareerPortalIntegration
//     Step B: QuestionnaireApi.GetQuestionnaire (Axios portal API)
// ─────────────────────────────────────────────────────────────────────────────
export async function fetchQuestionnaire(
  jobCodeID: number,
): Promise<{ status: number; data: QuestionItem[] }> {
  try {
    // Step A – SP read
    const jobUniqueItems: any[] = await SPServices.SPReadItems({
      Listname: ListNames.RecruitAppCareerPortalIntegration,
      Select: "*,JobCode/JobCode",
      Filter: [
        { FilterKey: "JobCodeId", Operator: "eq", FilterValue: jobCodeID },
        { FilterKey: "IsActive", Operator: "eq", FilterValue: 1 },
      ],
      FilterCondition: "and",
      Expand: "JobCode",
      Topcount: TOP,
      Orderby: "ID",
      Orderbydecorasc: true,
    });

    const jobUniqueKey: string = jobUniqueItems[0]?.JobUniqueKey ?? "";
    if (!jobUniqueKey) return { status: 404, data: [] };

    // Step B – portal Axios
    const response = await questionnaireService.getQuestionnaire(jobUniqueKey);
    const questions: QuestionItem[] = (response.data ?? []).map(
      (item: any, index: number) => ({
        id: index + 1,
        question: item?.question?.quesContent?.contentEn ?? "",
        questionFr: item?.question?.quesContent?.contentFr ?? "",
        answer:
          item?.question?.questionXAnswers?.[0]?.optContent?.contentEn ?? "",
        answerFr:
          item?.question?.questionXAnswers?.[0]?.optContent?.contentFr ?? "",
        rating: 0,
        header: "Q" + (index + 1),
      }),
    );
    return { status: 200, data: questions };
  } catch (err) {
    console.error("fetchQuestionnaire error:", err);
    return { status: 500, data: [] };
  }
}

