//     Source: HodViewScorecard.handleAssignPosition
//             + InterviewProcessService.AssignPositionID
//     Lists:  HRMSPositionIDMaster (read), HRMSSelectedCandidateDetailsByHOD (add),
//             HRMSPositionIDMaster (update)
// ─────────────────────────────────────────────────────────────────────────────
export async function assignPosition(
  payload: AssignPositionPayload,
  positionText: string,
  _positionKey: number,
) {
  try {
    const positionItems: any[] = await SPServices.SPReadItems({
      Listname: ListNames.HRMSPositionIDMaster,
      Select: "*,JobCode/JobCode",
      Filter: [
        { FilterKey: "PositionID", Operator: "eq", FilterValue: positionText },
      ],
      Expand: "JobCode",
    });
    if (!positionItems.length) return;
    const selectedPos = positionItems[0];

    await SPServices.SPAddItem({
      Listname: ListNames.HRMSSelectedCandidateDetailsByHOD,
      RequestJSON: { ...payload, PositionIDId: selectedPos.ID },
    });

    await SPServices.SPUpdateItem({
      Listname: ListNames.HRMSPositionIDMaster,
      RequestJSON: { PositionIDStatus: PositionStatus.RecruitmentInProgress },
      ID: selectedPos.ID,
    });
  } catch (err) {
    console.error("assignPosition error:", err);
  }
}

