// 16. submitLevel2ScoreSheet
//     Source: HodViewScorecard.Submit_fn (Level2 path)
//     Lists:  HRMSInterviewPanelDetails (read + update)
//             HRMSRecruitmentCandidatePersonalDetails (update – done in caller)
// ─────────────────────────────────────────────────────────────────────────────
export async function submitLevel2ScoreSheet(
  candidateID: number,
  currentUserEmailId: string,
  stateValueID: number,
): Promise<boolean> {
  try {
    const user = await getSP().web.siteUsers.getByEmail(currentUserEmailId)();
    const currentUserKey = user?.Id;

    const allPanels: any[] = await SPServices.SPReadItems({
      Listname: ListNames.HRMSInterviewPanelDetails,
      Select:
        "ID, CandidateID/ID, RecruitmentID/ID, InterviewLevel, InterviewPanel/Id, InterviewPanel/Title, InterviewPanel/EMail, IsScoreSheetUploaded",
      Expand: "InterviewPanel,RecruitmentID,CandidateID",
      Filter: [
        {
          FilterKey: "CandidateIDId",
          Operator: "eq",
          FilterValue: stateValueID,
        },
      ],
    });

    const matchingPanels = allPanels.filter(
      (p) => stateValueID === p.CandidateID?.ID,
    );
    const userPanels = matchingPanels.filter(
      (p) => p.InterviewPanel?.Id === Number(currentUserKey),
    );

    for (const panel of userPanels) {
      await SPServices.SPUpdateItem({
        Listname: ListNames.HRMSInterviewPanelDetails,
        RequestJSON: { IsScoreSheetUploaded: "Yes" },
        ID: panel.ID,
      });
    }

    // Re-read to check if ALL level-2 panels have uploaded
    const updatedPanels: any[] = await SPServices.SPReadItems({
      Listname: ListNames.HRMSInterviewPanelDetails,
      Select: "ID, CandidateID/ID, InterviewLevel, IsScoreSheetUploaded",
      Expand: "CandidateID",
      Filter: [
        {
          FilterKey: "CandidateID/Id",
          Operator: "eq",
          FilterValue: candidateID,
        },
      ],
    });

    const level2Panels = updatedPanels.filter(
      (p) =>
        p.CandidateID?.ID === candidateID && p.InterviewLevel === "Level 2",
    );
    const uploadedCount = level2Panels.filter(
      (p) => p.IsScoreSheetUploaded === "Yes",
    ).length;

    return uploadedCount === level2Panels.length;
  } catch (err) {
    console.error("submitLevel2ScoreSheet error:", err);
    return false;
  }
}

