// Private helper
// ─────────────────────────────────────────────────────────────
function _parseJson(raw: any): Record<string, number>[] {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  try { return JSON.parse(raw); } catch { return []; }
}

// ─────────────────────────────────────────────────────────────
// fetchScorecardCandidates
// ─────────────────────────────────────────────────────────────
export async function fetchScorecardCandidates(
  recruitmentID: number,
  jobCodeID: number,
  currentUserEmail: string = "",
  candidateFilter: any[] = []
): Promise<ScorecardCandidateRow[]> {
  try {
    // Use caller-provided filter OR build the correct default (mirrors old CandidateList exactly)
    const filter: any[] = candidateFilter && candidateFilter.length
      ? [...candidateFilter]
      : [
          { FilterKey: "RecruitmentIDId", Operator: "eq", FilterValue: recruitmentID },
          { FilterKey: "JobCodeId",        Operator: "eq", FilterValue: jobCodeID },
          {
            FilterKey: "StatusId",
            Operator: "in",
            // Exact StatusId array from old CandidateList.tsx (includes ALL HOD statuses)
            FilterValue: [
              121, // PendingwithHODtoselectthecandidate
              122, // Selected
              123, // OnHoldbyHOD
              15,  // RejectedbyHOD
              130, // PendingwithHODtoAssignPositionID
              127, // PendingwithHODtoselectthecandidateLevel2
              165, // CandidateOnHoldbyHODLevel1
              166, // CandidateOnHoldbyHODLevel2
              167, // CandidateRejectedbyHODLevel1
              168, // CandidateRejectedbyHODLevel2
            ],
          },
          // NOTE: Old CandidateList.tsx includes ItemCreated:"No" but some SP records
          // have null/empty ItemCreated — we keep this filter off to return all HOD-status
          // candidates regardless of ItemCreated value, matching actual SP data behaviour.
        ];

    console.log(
      "--> fetchScorecardCandidates: recruitmentID=", recruitmentID,
      "jobCodeID=", jobCodeID,
      "filter=", JSON.stringify(filter)
    );

    const res: any[] = await SPServices.SPReadItems({
      Listname: ListNames.HRMSRecruitmentCandidatePersonalDetails,
      // Mirror old GetCombinedCandidatePositionDetails Select/Expand exactly
      Select: "*,JobCode/JobCode,AssignByInterviewPanel/EMail,RecruitmentID/ID,Status/ID,Status/StatusDescription,ID",
      Expand: "JobCode,AssignByInterviewPanel,RecruitmentID,Status",
      FilterCondition: "and",
      Filter: filter,
      Topcount: 1000, // matches old count.Topcount from Config.ts
    });

    console.log("--> fetchScorecardCandidates: records fetched =", res?.length);

    // ── GPA Calculation — mirrors old InterviewProcessService.getInterviewPanelDetails ──
    // For each candidate:
    //   1. Fetch their InterviewPanel rows (Level 1)
    //   2. For each panel row fetch its ScoreCard
    //   3. Sum overall scores (8 criteria) + question scores
    //   4. maxOverallScore = level1Count * 40, maxQuestionScore = questionData.length * 3
    //   5. GPA = (combinedScore / maxPossibleScore) * 5, floored to 2 dp
    const enrichedWithGPA = await Promise.all(
      (res || []).map(async (item: any) => {
        let gpa: number | null = null;
        try {
          const panels: any[] = await SPServices.SPReadItems({
            Listname: ListNames.HRMSInterviewPanelDetails,
            Select: "ID,InterviewLevel,CandidateID/ID",
            Expand: "CandidateID",
            Filter: [{ FilterKey: "CandidateID/Id", Operator: "eq", FilterValue: item.ID }],
          });

          const level1Count = panels.filter(p => p.InterviewLevel === "Level 1").length;
          const maxOverallScore = level1Count * 40;

          let sumOverall = 0;
          let sumQuestion = 0;
          let maxQuestion = 0;

          for (const panel of panels) {
            const scorecards: any[] = await SPServices.SPReadItems({
              Listname: ListNames.HRMSCandidateScoreCard,
              Select: "*",
              Filter: [{ FilterKey: "InterviewPanelIDId", Operator: "eq", FilterValue: panel.ID }],
            });

            if (scorecards.length > 0) {
              const sc = scorecards[0];
              const totalScore =
                (Number(sc.RelevantQualification) || 0) +
                (Number(sc.ReleventExperience) || 0) +
                (Number(sc.Knowledge) || 0) +
                (Number(sc.EnergyLevel) || 0) +
                (Number(sc.MeetJobRequirement) || 0) +
                (Number(sc.ContributeTowardsCultureRequried) || 0) +
                (Number(sc.Experience) || 0) +
                (Number(sc.OtherCriteriaScore) || 0);

              const questionData: any[] = _parseJson(sc.QuestionJson);
              const questionScore = questionData.reduce((sum: number, q: any) => {
                return sum + (Number(Object.values(q)[0]) || 0);
              }, 0);

              sumOverall += totalScore;
              sumQuestion += questionScore;
              maxQuestion += questionData.length * 3;
            }
          }

          const combined = sumOverall + sumQuestion;
          const maxPossible = maxOverallScore + maxQuestion;
          if (maxPossible > 0) {
            gpa = Math.floor((combined / maxPossible) * 5 * 100) / 100;
          }
        } catch (e) {
          console.warn("GPA calc error for candidate", item.ID, e);
        }

        return {
          id: item.ID,
          recruitmentID: item.RecruitmentID?.ID || recruitmentID,
          jobCode: item.JobCode?.JobCode || "",
          jobCodeID: item.JobCodeId || jobCodeID,
          fullName: [item.FristName, item.MiddleName, item.LastName]
            .filter(Boolean).join(" ").trim(),
          nationality: item.Nationality || "",
          gender: item.Gender || "",
          status: item.Status?.StatusDescription || item.Status || "",
          statusId: item.StatusId || item.Status?.ID || 0,
          interviewDate: item.InterviewDate || "",
          interviewLevel: item.InterviewLevel || "",
          grade: item.JobGrade || "",
          department: item.Department || "",
          gpa: gpa !== null ? String(gpa) : "",
          positionTitle: item.PositionTitle || "",
          disability: item.Disability || "",
          jobTitle: item.JobTitle || "",
        } as ScorecardCandidateRow;
      })
    );

    return enrichedWithGPA;
  } catch (e) {
    console.error("fetchScorecardCandidates error", e);
    return [];
  }
}